(() => {
'use strict';
const app=document.getElementById('app');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let count=2,names=Array(10).fill(''),rounds=5,duration=60,players=[],history=[],letters=[],round=0,turn=0,letter='',stage='setup',deadline=0,ticker=null,draft=Array(6).fill('');
let gamesCompleted=0,gameOffset=0,order=[],hasStarted=false;
const activePlayer=()=>order[turn];
document.getElementById('rules').onclick=()=>document.getElementById('rulesDialog').showModal();
function setup(){stage='setup';clearInterval(ticker);app.innerHTML=`<div class="intro"><div><div class="eyebrow">LE GRAND CLASSIQUE, TOUS ENSEMBLE</div><h1>À vos lettres.<br>Prêts ? Jouez.</h1><p class="muted">Réunissez la bande. Une lettre par joueur, six catégories et une minute pour faire la différence.</p></div><span class="tag">2 à 10 joueurs · Sur un appareil</span></div><div class="setup-layout"><form class="card" id="setupForm"><div class="section-title"><h2>Qui est de la partie ?</h2><div class="counter"><button type="button" id="minus" aria-label="Retirer un joueur" ${count===2?'disabled':''}>−</button><span>${count}</span><button type="button" id="plus" aria-label="Ajouter un joueur" ${count===10?'disabled':''}>+</button></div></div><div class="names">${Array.from({length:count},(_,i)=>`<div class="field"><label for="name${i}">Joueur ${i+1}</label><input id="name${i}" data-name="${i}" placeholder="Prénom du joueur ${i+1}" value="${escapeHTML(names[i])}" maxlength="24" autocomplete="off"></div>`).join('')}</div><div class="options"><div class="field"><label for="rounds">Nombre de manches</label><input id="rounds" type="number" inputmode="numeric" min="1" step="1" required value="${rounds}" aria-describedby="roundsHelp"><small id="roundsHelp">Saisissez un nombre entier, à partir de 1.</small></div><div class="field"><label for="duration">Temps par joueur</label><select id="duration">${[15,30,60].map(n=>`<option value="${n}" ${duration===n?'selected':''}>${n} secondes</option>`).join('')}</select></div></div><p class="error" id="nameError" role="alert"></p><button class="primary wide">Vérifier les paramètres</button><p class="notice">Vous pourrez revenir aux réglages avant de démarrer.</p></form><aside class="card preview"><div class="eyebrow">VOTRE TERRAIN DE JEU</div><div class="tiles" aria-hidden="true"><span class="tile">B</span><span class="tile">A</span><span class="tile">C</span></div><h2>Six occasions<br>de marquer.</h2><p>Le mot vous échappe ? Passez à la catégorie suivante et revenez-y après.</p><div class="categories">${CATEGORIES.map((c,i)=>`<div class="category-chip">${ICONS[i]} &nbsp;${c}</div>`).join('')}</div><div class="preview-bottom"><strong>10</strong> points par mot valide · <strong>60</strong> maximum par manche</div></aside></div>`;
app.querySelectorAll('[data-name]').forEach(el=>el.oninput=()=>names[Number(el.dataset.name)]=el.value);document.getElementById('minus').onclick=()=>{count--;setup()};document.getElementById('plus').onclick=()=>{count++;setup()};document.getElementById('rounds').oninput=e=>rounds=e.target.value;document.getElementById('duration').onchange=e=>duration=Number(e.target.value);document.getElementById('setupForm').onsubmit=e=>{e.preventDefault();rounds=Number(document.getElementById('rounds').value);if(!Number.isSafeInteger(rounds)||rounds<1){document.getElementById('nameError').textContent='Saisissez un nombre entier de manches supérieur ou égal à 1.';return;}const chosen=names.slice(0,count).map((n,i)=>n.trim()||`Joueur ${i+1}`);if(new Set(chosen.map(normalize)).size!==count){document.getElementById('nameError').textContent='Choisissez un nom différent pour chaque joueur.';return;}players=chosen;confirmSetup();};}
function confirmSetup(){
 stage='confirm';gameOffset=gamesCompleted%players.length;
 const firstOrder=players.map((_,i)=>(i+gameOffset)%players.length);
 app.innerHTML=`<section class="card ready"><div class="eyebrow">AVANT DE JOUER</div><h1>Tout est prêt ?</h1><p><strong>${players.length} joueurs · ${rounds} manche${rounds>1?'s':''} · ${duration} secondes</strong></p><p class="muted">Ordre de la première manche :<br>${firstOrder.map(i=>escapeHTML(players[i])).join(' · ')}</p><p class="notice">Une lettre différente pour chaque joueur dans une même manche. Le premier joueur change à chaque manche et à chaque nouvelle partie.</p><button class="primary wide" id="launch">Lancer la partie</button><button class="quiet wide" id="settings">Revenir aux paramètres</button></section>`;
 document.getElementById('settings').onclick=setup;
 document.getElementById('launch').onclick=beginGame;window.scrollTo(0,0);
}
function beginGame(){history=[];letters=[];round=0;hasStarted=false;nextRound();}
function chooseLetter(excluded){const available='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').filter(c=>!excluded.includes(c));const value=new Uint32Array(1);crypto.getRandomValues(value);return available[Math.floor(value[0]/4294967296*available.length)];}
function nextRound(){
 round++;turn=0;order=players.map((_,i)=>(i+gameOffset+round-1)%players.length);
 const assigned=[],used=[];
 for(const player of order){const previous=history.at(-1)?.letters[player];const picked=chooseLetter(previous?[...used,previous]:used);assigned[player]=picked;used.push(picked);}
 letters.push(...used);history.push({letters:assigned,order:[...order],answers:[]});ready();
}
function renderGameHeader(){return `<div class="game-top"><div><div class="round-label">MANCHE ${round} / ${rounds}</div><h1>${stage==='results'?'Les mots ont parlé.':'À vous de jouer.'}</h1></div><span class="tag">${duration} s · 6 catégories</span></div>`;}
function ready(){stage='ready';letter=history[round-1].letters[activePlayer()];app.innerHTML=renderGameHeader()+`<section class="card ready"><div class="eyebrow">JOUEUR ${turn+1} SUR ${players.length}</div><h2 style="margin-top:16px">Passez l’appareil à<br>${escapeHTML(players[activePlayer()])}.</h2><div class="big-letter">${letter}</div><p class="muted">Tous vos mots doivent commencer par <strong>${letter}</strong>.<br>Vous avez ${duration} secondes pour les six catégories.</p><button class="primary" id="ready">Je suis prêt · Démarrer le chrono</button>${!hasStarted?'<button class="quiet wide" id="backSettings">Modifier les paramètres</button>':''}<p class="notice">Les autres joueurs, détournez les yeux !</p></section>`;document.getElementById('ready').onclick=startTurn;if(!hasStarted)document.getElementById('backSettings').onclick=setup;window.scrollTo(0,0);}
function startTurn(){hasStarted=true;stage='play';draft=Array(6).fill('');app.innerHTML=renderGameHeader()+`<div class="turn-layout"><aside class="card clock-card"><div><div class="big-letter">${letter}</div></div><div><div class="timer" id="clock" role="timer" aria-label="Secondes restantes">${duration}</div><span>secondes restantes</span><div class="progress"><span id="bar" style="width:100%"></span></div></div></aside><form class="card" id="answersForm"><div class="section-title"><h2>${escapeHTML(players[activePlayer()])}</h2><span class="turn-counter">${turn+1} / ${players.length}</span></div><div class="answer-fields">${CATEGORIES.map((c,i)=>`<div class="field"><label for="answer${i}">${ICONS[i]} &nbsp;${c}</label><input id="answer${i}" data-answer="${i}" placeholder="${c} en ${letter}…" maxlength="70" autocomplete="off" spellcheck="false"></div>`).join('')}</div><button class="primary wide">Valider mes réponses</button><p class="notice">À la fin du chrono, vos réponses sont enregistrées automatiquement.</p></form></div>`;deadline=Date.now()+duration*1000;app.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{if(Date.now()>=deadline){finishTurn();return}draft[Number(el.dataset.answer)]=el.value;});document.getElementById('answersForm').onsubmit=e=>{e.preventDefault();finishTurn()};document.getElementById('answer0').focus();ticker=setInterval(tick,100);tick();}
function tick(){if(stage!=='play')return;const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));document.getElementById('clock').textContent=remaining;document.getElementById('clock').classList.toggle('low',remaining<=10);document.getElementById('bar').style.width=Math.max(0,(deadline-Date.now())/(duration*1000)*100)+'%';if(!remaining)finishTurn();}
document.addEventListener('visibilitychange',()=>{if(stage==='play')tick()});
function finishTurn(){if(stage!=='play')return;stage='saving';clearInterval(ticker);history[round-1].answers[activePlayer()]=draft.map((w,i)=>({word:w.trim(),...assess(w,i,letter)}));turn++;if(turn<players.length)ready();else results();}
function totals(){return players.map((name,i)=>({name,index:i,score:history.reduce((total,r)=>total+(r.answers[i]||[]).reduce((s,a)=>s+a.points,0),0)})).sort((a,b)=>b.score-a.score||a.index-b.index);}
function ranking(){let previous=null,rank=0;return totals().map((p,i)=>{if(previous!==p.score)rank=i+1;previous=p.score;return `<div class="rank-row"><span class="position">${rank}</span><strong>${escapeHTML(p.name)}</strong><span class="score">${p.score}</span><small>pts</small></div>`}).join('');}
function results(){stage='results';app.innerHTML=renderGameHeader()+`<div class="results-grid"><section><p class="notice">Une lettre par joueur · 10 points par mot reconnu. Un mot absent du répertoire vaut 0 jusqu’à validation par le groupe. Les légumes sont classés selon leur usage culinaire.</p>${players.map((p,j)=>`<details class="card result-player" open><summary><span>${escapeHTML(p)} · Lettre ${history[round-1].letters[j]}</span><span>${history[round-1].answers[j].reduce((s,a)=>s+a.points,0)} / 60</span></summary>${history[round-1].answers[j].map((a,i)=>`<div class="answer-row"><span>${CATEGORIES[i]}</span><div><strong>${escapeHTML(a.word)||'—'}</strong><small>${escapeHTML(a.reason)}</small>${a.eligible?`<button data-review="${j},${i}">Contester la correction</button>`:''}</div><span class="points ${a.points?'':'zero'}">${a.points} pts</span></div>`).join('')}</details>`).join('')}</section><aside><div class="card"><h2>Le classement</h2>${ranking()}<button id="next" class="primary wide">${round===rounds?'Voir le podium':'Manche suivante'}</button></div><div class="card examples"><div class="eyebrow">LES MOTS DE L’ANIMATEUR</div>${players.map((p,j)=>`<details class="player-examples" ${j===0?'open':''}><summary>${escapeHTML(p)} · ${history[round-1].letters[j]}</summary>${CATEGORIES.map((c,i)=>`<div class="example"><span>${c}</span><strong>${escapeHTML(WORDS[i].find(w=>normalize(w).startsWith(normalize(history[round-1].letters[j])))||'Aucun exemple disponible')}</strong></div>`).join('')}</details>`).join('')}<p class="notice">D’autres réponses peuvent être valides.</p></div></aside></div>`;document.getElementById('next').onclick=()=>round===rounds?final():nextRound();app.querySelectorAll('[data-review]').forEach(btn=>btn.onclick=()=>{const [j,i]=btn.dataset.review.split(',').map(Number);review(j,i)});window.scrollTo(0,0);}
function review(j,i){const a=history[round-1].answers[j][i];const reviewLetter=history[round-1].letters[j];const dialog=document.createElement('dialog');dialog.innerHTML=`<h2>À vous de trancher</h2><p><strong>${escapeHTML(a.word)}</strong> est-il bien un ${CATEGORIES[i].toLowerCase()} commençant par ${reviewLetter} ?</p><p class="muted">Décidez ensemble. Le score sera immédiatement recalculé.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="primary" data-points="10">Valider · 10 points</button><button class="quiet" data-points="0">Refuser · 0 point</button><button class="quiet" id="cancelReview">Annuler</button></div>`;document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.querySelectorAll('[data-points]').forEach(b=>b.onclick=()=>{a.points=Number(b.dataset.points);a.reason=a.points?'Validé par le groupe':'Refusé par le groupe';dialog.close();results();});dialog.querySelector('#cancelReview').onclick=()=>dialog.close();dialog.showModal();}
function final(){if(stage!=='final')gamesCompleted++;stage='final';const scores=totals(),winners=scores.filter(p=>p.score===scores[0].score);app.innerHTML=`<div class="final-board"><section class="winner"><div class="eyebrow">PARTIE TERMINÉE · ${rounds} MANCHES</div><h1>${winners.map(p=>escapeHTML(p.name)).join(' &amp; ')}</h1><p>${winners.length>1?'Premiers ex æquo. Bien joué !':'Remporte la partie. Bien joué !'}</p><div class="score">${scores[0].score} points</div></section><section class="card"><h2>Le classement final</h2>${ranking()}<p class="notice">Lettres jouées : ${[...new Set(letters)].join(' · ')}</p><button id="replay" class="primary wide">Rejouer avec la même équipe</button><button id="new" class="quiet wide">Configurer une nouvelle partie</button></section></div>`;document.getElementById('replay').onclick=confirmSetup;document.getElementById('new').onclick=setup;window.scrollTo(0,0);}
setup();

})();
